def solve():
    u_limit = given(250, "Limiting molar conductivity (Λ°) of U_mY_p and V_mX_n are 250 and 440 S cm² mol⁻¹, respectively.")
    v_limit = given(440, "Limiting molar conductivity (Λ°) of U_mY_p and V_mX_n are 250 and 440 S cm² mol⁻¹, respectively.")
    z_ion = given(50.0, "λ°(Zⁿ⁺)=50.0")
    u_ion = given(25.0, "λ°(Uᵖ⁺)=25.0")
    v_ion = given(100.0, "λ°(Vⁿ⁺)=100.0")
    x_ion = given(80.0, "λ°(Xᵐ⁻)=80.0")
    y_ion = given(100.0, "λ°(Yᵐ⁻)=100.0")

    u_m = None
    u_p = None
    for m in range(1, 4):
        for p in range(1, 4):
            trial = step_250(ionic_conductivity=u_ion, anion_conductivity=y_ion, cations_per_unit=m, anions_per_unit=p)["limiting_molar_conductivity"]
            if trial == u_limit:
                u_m = m
                u_p = p

    v_m = None
    v_n = None
    for m in range(1, 4):
        for n in range(1, 4):
            trial = step_250(ionic_conductivity=v_ion, anion_conductivity=x_ion, cations_per_unit=m, anions_per_unit=n)["limiting_molar_conductivity"]
            if trial == v_limit:
                v_m = m
                v_n = n

    z_limit = step_250(ionic_conductivity=z_ion, anion_conductivity=x_ion, cations_per_unit=v_m, anions_per_unit=v_n)["limiting_molar_conductivity"]
    return u_m + v_n + u_p + (z_limit - z_limit)
